package io.github.jesterportfolio.hearth.administration;

import java.nio.file.*;import java.nio.channels.*;import java.util.*;import java.io.*;
import java.util.regex.*;
import org.postgresql.ds.PGSimpleDataSource;
import io.github.jesterportfolio.hearth.economy.*;
import io.github.jesterportfolio.hearth.survival.economy.NativeEconomySettings;
import io.github.jesterportfolio.hearth.survival.market.MarketSettings;
import io.github.jesterportfolio.hearth.survival.platform.ConfigurationChanges;

/** 운영 실행은 별도 승인 대상. 정지/파일 잠금·원본 보존·고정 계획으로만 정책을 교체한다. */
public final class NativePolicyTool {
    private static Properties props(byte[] bytes)throws Exception{var p=new Properties();p.load(new ByteArrayInputStream(bytes));return p;}
    private static byte[] bytes(Properties p)throws Exception{var out=new ByteArrayOutputStream();p.store(out,"Hearth reviewed policy binding");return out.toByteArray();}
    private static byte[] read(Path path)throws Exception{if(!path.equals(path.toRealPath())||!Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS)||Files.size(path)>1048576)throw new IOException("POLICY_PATH");return Files.readAllBytes(path);}
    private static void write(Path path,byte[] bytes)throws Exception{Files.write(path,bytes,StandardOpenOption.CREATE_NEW);try(var c=FileChannel.open(path,StandardOpenOption.WRITE)){c.force(true);}}
    private static void replace(Path path,byte[] bytes)throws Exception{Path tmp=path.resolveSibling(path.getFileName()+".policy-writing");write(tmp,bytes);Files.setPosixFilePermissions(tmp,Files.getPosixFilePermissions(path));Files.move(tmp,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
    private static int[] sectionRange(String text,String name)throws IOException{var m=Pattern.compile("(?m)^"+Pattern.quote(name)+":\\r?\\n").matcher(text);if(!m.find())throw new IOException("POLICY_SECTION");int start=m.end();if(m.find())throw new IOException("POLICY_DUPLICATE_SECTION");var end=Pattern.compile("(?m)^[^ #\\r\\n][^\\r\\n]*:").matcher(text);int stop=text.length();while(end.find())if(end.start()>=start){stop=end.start();break;}return new int[]{start,stop};}
    private static Map<String,Object> section(String text,String name)throws IOException{var range=sectionRange(text,name);var out=new HashMap<String,Object>();for(String line:text.substring(range[0],range[1]).split("\\R")){if(line.isBlank()||line.stripLeading().startsWith("#"))continue;var m=Pattern.compile("^  ([a-z][a-z0-9-]*): (.+?)\\s*$").matcher(line);if(!m.matches())throw new IOException("POLICY_PLAIN_SCALAR_SECTION_REQUIRED");String raw=m.group(2).strip();int comment=raw.indexOf(" #");if(comment>=0)raw=raw.substring(0,comment).strip();Object value=raw;if(raw.matches("-?[0-9]+"))value=Integer.valueOf(raw);else if(raw.equals("true")||raw.equals("false"))value=Boolean.valueOf(raw);else if(raw.length()>=2&&((raw.startsWith("\"")&&raw.endsWith("\""))||(raw.startsWith("'")&&raw.endsWith("'"))))value=raw.substring(1,raw.length()-1);if(out.put(m.group(1),value)!=null)throw new IOException("POLICY_DUPLICATE_KEY");}return out;}
    private static String patchMarket(String text,Properties changes)throws IOException{var range=sectionRange(text,"market-automation");String body=text.substring(range[0],range[1]);for(String key:changes.stringPropertyNames()){String row="  "+key+": "+Integer.parseInt(changes.getProperty(key));var pattern=Pattern.compile("(?m)^  "+Pattern.quote(key)+": [^\\r\\n]*$");if(pattern.matcher(body).find())body=pattern.matcher(body).replaceFirst(Matcher.quoteReplacement(row));else body+=(body.endsWith("\n")?"":"\n")+row+"\n";}return text.substring(0,range[0])+body+text.substring(range[1]);}
    public static void main(String[] args)throws Exception{
        if(args.length!=6||!args[5].equals("offline-confirmed")||!Set.of("stage","apply","rollback").contains(args[0]))throw new IllegalArgumentException("stage|apply|rollback PAPER_ROOT economy|market CANDIDATE PLAN_DIR offline-confirmed");
        Path paper=Path.of(args[1]).toRealPath(),data=paper.resolve("plugins/Hearth").toRealPath(),plan=Path.of(args[4]).toAbsolutePath();String kind=args[2];if(!Set.of("economy","market").contains(kind)||!Files.getOwner(paper).equals(Files.getOwner(data)))throw new IOException("POLICY_OWNER");
        var channels=new ArrayList<FileChannel>();var locks=new ArrayList<FileLock>();try{
            try(var paths=Files.walk(paper)){int count=0;for(var path:paths.toList()){if(++count>100000||Files.isSymbolicLink(path))throw new IOException("POLICY_TREE_PATH");String name=path.getFileName().toString();if(name.endsWith(".active")||name.equals("postmaster.pid"))throw new IOException("POLICY_SERVER_MUST_BE_STOPPED");if(name.equals("session.lock")){var c=FileChannel.open(path,StandardOpenOption.READ,StandardOpenOption.WRITE);channels.add(c);var lock=c.tryLock();if(lock==null)throw new IOException("POLICY_SERVER_RUNNING");locks.add(lock);}}}
            for(String folder:List.of("native-economy-pending","rpg-death-pending")){Path dir=data.resolve(folder);if(Files.isDirectory(dir))try(var files=Files.list(dir)){if(files.findAny().isPresent())throw new IOException("POLICY_PENDING_OPERATIONS");}}
            String configText=new String(read(data.resolve("config.yml")),java.nio.charset.StandardCharsets.UTF_8);var settings=NativeEconomySettings.parse(section(configText,"survival-economy"));var binding=props(read(data.resolve("native-economy.properties")));if(!settings.realm().toString().equals(binding.getProperty("realm")))throw new IOException("POLICY_REALM");
            Path marker=data.resolve("native-policy-migration.pending");Properties manifest;
            if(args[0].equals("stage")){if(Files.exists(marker)||Files.exists(plan,LinkOption.NOFOLLOW_LINKS)||!plan.getParent().equals(plan.getParent().toRealPath()))throw new IOException("POLICY_FRESH_PLAN_REQUIRED");Files.createDirectory(plan,java.nio.file.attribute.PosixFilePermissions.asFileAttribute(java.nio.file.attribute.PosixFilePermissions.fromString("rwx------")));manifest=new Properties();manifest.setProperty("format","1");manifest.setProperty("request",UUID.randomUUID().toString());manifest.setProperty("realm",settings.realm().toString());manifest.setProperty("kind",kind);manifest.setProperty("paper",paper.toString());manifest.setProperty("state","STAGED");
                byte[] candidate=read(Path.of(args[3]).toAbsolutePath()),before,after,beforeBinding,afterBinding;
                if(kind.equals("economy")){manifest.setProperty("target",settings.contentFile());manifest.setProperty("binding","native-economy.properties");before=read(data.resolve(settings.contentFile()));var old=EconomyContent.parse(props(before));var next=EconomyPolicyMigration.validate(props(before),props(candidate));if(!old.fingerprint().equals(binding.getProperty("content")))throw new IOException("POLICY_BINDING");manifest.setProperty("before",old.fingerprint());manifest.setProperty("after",next.fingerprint());after=candidate;beforeBinding=read(data.resolve("native-economy.properties"));binding.setProperty("content",next.fingerprint());afterBinding=bytes(binding);
                }else{manifest.setProperty("target","config.yml");manifest.setProperty("binding","market-automation.properties");before=read(data.resolve("config.yml"));var old=MarketSettings.parse(section(configText,"market-automation"));var values=props(candidate);var fields=Set.of("interval-ticks","confirmations","minimum-hold-ticks","reserve-low-bps","reserve-normal-bps","reserve-high-bps","buffer-ticks","low-stock-bps");if(!fields.containsAll(values.stringPropertyNames())||values.isEmpty())throw new IOException("POLICY_MARKET_FIELDS");String patched=patchMarket(configText,values);var next=MarketSettings.parse(section(patched,"market-automation"));manifest.setProperty("before",old.policy().fingerprint());manifest.setProperty("after",next.policy().fingerprint());after=patched.getBytes(java.nio.charset.StandardCharsets.UTF_8);beforeBinding=read(data.resolve("market-automation.properties"));var marketBinding=props(beforeBinding);if(!settings.realm().toString().equals(marketBinding.getProperty("realm"))||!old.policy().fingerprint().equals(marketBinding.getProperty("policy")))throw new IOException("POLICY_MARKET_BINDING");marketBinding.setProperty("policy",next.policy().fingerprint());afterBinding=bytes(marketBinding);}
                if(manifest.getProperty("before").equals(manifest.getProperty("after")))throw new IOException("POLICY_UNCHANGED");for(var pair:Map.of("before-file",before,"after-file",after,"before-binding",beforeBinding,"after-binding",afterBinding).entrySet()){write(plan.resolve(pair.getKey()),pair.getValue());manifest.setProperty(pair.getKey()+"-sha256",ConfigurationChanges.hash(pair.getValue()));}write(plan.resolve("manifest.properties"),bytes(manifest));System.out.println("POLICY_STAGED request="+manifest.getProperty("request")+" before="+manifest.getProperty("before")+" after="+manifest.getProperty("after"));return;
            }
            if(!plan.equals(plan.toRealPath()))throw new IOException("POLICY_PLAN_PATH");manifest=props(read(plan.resolve("manifest.properties")));if(!"1".equals(manifest.getProperty("format"))||!kind.equals(manifest.getProperty("kind"))||!paper.toString().equals(manifest.getProperty("paper"))||!settings.realm().toString().equals(manifest.getProperty("realm")))throw new IOException("POLICY_PLAN_SCOPE");
            String target=manifest.getProperty("target"),bindingName=manifest.getProperty("binding");if(!target.equals(kind.equals("economy")?settings.contentFile():"config.yml")||!bindingName.equals(kind.equals("economy")?"native-economy.properties":"market-automation.properties"))throw new IOException("POLICY_PLAN_TARGET");
            for(String key:List.of("before-file","after-file","before-binding","after-binding"))if(!ConfigurationChanges.hash(read(plan.resolve(key))).equals(manifest.getProperty(key+"-sha256")))throw new IOException("POLICY_PLAN_CHANGED");
            String token=manifest.getProperty("request")+"\n"+plan+"\n";if(Files.exists(marker)){if(!Files.readString(marker).equals(token))throw new IOException("POLICY_OTHER_PENDING");}else write(marker,token.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            boolean rollback=args[0].equals("rollback");String wanted=rollback?"before":"after";
            for(var pair:Map.of(target,"file",bindingName,"binding").entrySet()){String actual=ConfigurationChanges.hash(read(data.resolve(pair.getKey())));if(!Set.of(manifest.getProperty("before-"+pair.getValue()+"-sha256"),manifest.getProperty("after-"+pair.getValue()+"-sha256")).contains(actual))throw new IOException("POLICY_EXTERNAL_CHANGE");}
            var source=new PGSimpleDataSource();source.setServerNames(new String[]{settings.host()});source.setPortNumbers(new int[]{settings.port()});source.setDatabaseName(settings.database());source.setUser(settings.user());source.setPassword(Objects.requireNonNull(System.getenv(settings.passwordEnvironment()),"POLICY_PASSWORD_ENV"));source.setConnectTimeout(2);source.setSocketTimeout(5);try(var c=source.getConnection()){EconomyPolicyMigration.swap(c,settings.realm(),UUID.fromString(manifest.getProperty("request")),kind,manifest.getProperty("before"),manifest.getProperty("after"),rollback);}
            for(var pair:Map.of(target,"file",bindingName,"binding").entrySet())if(!ConfigurationChanges.hash(read(data.resolve(pair.getKey()))).equals(manifest.getProperty(wanted+"-"+pair.getValue()+"-sha256")))replace(data.resolve(pair.getKey()),read(plan.resolve(wanted+"-"+pair.getValue())));
            manifest.setProperty("state",rollback?"ROLLED_BACK":"COMMITTED");replace(plan.resolve("manifest.properties"),bytes(manifest));if(!Files.readString(marker).equals(token))throw new IOException("POLICY_MARKER_CHANGED");Files.delete(marker);System.out.println("POLICY_"+manifest.getProperty("state")+" request="+manifest.getProperty("request"));
        }finally{for(var lock:locks)lock.close();for(var c:channels)c.close();}
    }
}
